queries.HomeStats:
query HomeStats {
  stats {
    indexed_height
    latest_block_time
    bucket_count
    block_count
    transfer_count
    proof_count
    circuit_count
  }
}

queries.LatestBlocks:
query LatestBlocks($limit: Int = 10) {
  blocks(where: {canonical: {_eq: true}}, order_by: {height: desc}, limit: $limit) {
    ...BlockRow
  }
}

fragment BlockRow on blocks {
  hash
  height
  time
  miner
  transfer_count
  registration_count
  proof_count
  fee_total
}

queries.Search:
query Search($q: String!) {
  search(args: {q: $q}) {
    kind
    id
    height
  }
}

queries.Blocks:
query Blocks($before: bigint = 9007199254740991, $limit: Int = 20) {
  blocks(
    where: {canonical: {_eq: true}, height: {_lt: $before}}
    order_by: {height: desc}
    limit: $limit
  ) {
    ...BlockRow
  }
}

fragment BlockRow on blocks {
  hash
  height
  time
  miner
  transfer_count
  registration_count
  proof_count
  fee_total
}

queries.Transaction:
query Transaction($txid: String!) {
  transfers(where: {txid: {_eq: $txid}}, order_by: {canonical: desc}) {
    ...TransferRow
  }
  circuits(where: {txid: {_eq: $txid}}) {
    ...RegistrationRow
    registered_block
    registered_height
    registered_time
    canonical
  }
  proofs(where: {request_txid: {_eq: $txid}}, order_by: {canonical: desc}) {
    proof_hash
    height
    canonical
  }
}

fragment TransferRow on transfers {
  txid
  block_hash
  height
  time
  position
  canonical
  sender
  recipient
  amount
  fee
  nonce
  sort_key
}

fragment RegistrationRow on circuits {
  txid
  circuit_id
  proof_system
  constraint_count
  registrant
  fee
}

queries.Circuits:
query Circuits($filter: circuits_bool_exp = {}, $before: String = "~", $limit: Int = 20) {
  circuits(
    where: {_and: [$filter, {canonical: {_eq: true}}, {sort_key: {_lt: $before}}]}
    order_by: {sort_key: desc}
    limit: $limit
  ) {
    ...CircuitRow
  }
}

fragment CircuitRow on circuits {
  circuit_id
  proof_system
  constraint_count
  registrant
  registered_height
  proof_count
  sort_key
}

queries.CircuitProofs:
query CircuitProofs($circuitId: String!, $before: String = "~", $limit: Int = 20) {
  proofs(
    where: {circuit_id: {_eq: $circuitId}, canonical: {_eq: true}, sort_key: {_lt: $before}}
    order_by: {sort_key: desc}
    limit: $limit
  ) {
    ...ProofRow
  }
}

fragment ProofRow on proofs {
  proof_hash
  request_txid
  height
  time
  position
  circuit_id
  proof_system
  client
  fee
  usage_counter
  sort_key
}

queries.Address:
query Address($address: String!) {
  addresses(where: {address: {_eq: $address}}) {
    address
    txs_sent
    txs_received
    proof_requests
    circuits_registered
    blocks_mined
    first_seen_height
  }
}

queries.AddressTxs:
query AddressTxs($address: String!, $filter: address_txs_bool_exp = {}, $before: String = "~", $limit: Int = 20) {
  address_txs(
    where: {_and: [$filter, {address: {_eq: $address}}, {sort_key: {_lt: $before}}]}
    order_by: {sort_key: desc}
    limit: $limit
  ) {
    direction
    kind
    txid
    height
    time
    position
    sender
    recipient
    amount
    fee
    nonce
    circuit_id
    proof_hash
    sort_key
  }
}

queries.MinedBlocks:
query MinedBlocks($miner: String!, $before: bigint = 9007199254740991, $limit: Int = 20) {
  blocks(
    where: {miner: {_eq: $miner}, canonical: {_eq: true}, height: {_lt: $before}}
    order_by: {height: desc}
    limit: $limit
  ) {
    ...BlockRow
  }
}

fragment BlockRow on blocks {
  hash
  height
  time
  miner
  transfer_count
  registration_count
  proof_count
  fee_total
}

queries.Mining:
query Mining {
  stats {
    block_count
    avg_block_interval_s
  }
  miner_shares(order_by: {blocks: desc}) {
    miner
    blocks
    share
    last_block_height
  }
  useful_work(order_by: {proof_system: asc}) {
    proof_system
    proof_count
    useful_work
  }
}

subscriptions.HomeStats:
subscription HomeStats {
  stats {
    indexed_height
    latest_block_time
    bucket_count
    block_count
    transfer_count
    proof_count
    circuit_count
  }
}

subscriptions.LatestBlocks:
subscription LatestBlocks($limit: Int = 10) {
  blocks(where: {canonical: {_eq: true}}, order_by: {height: desc}, limit: $limit) {
    ...BlockRow
  }
}

fragment BlockRow on blocks {
  hash
  height
  time
  miner
  transfer_count
  registration_count
  proof_count
  fee_total
}
